parameters.jsCode:
const body = $('Selbstauskunft eingereicht Webhook').item.json.body ?? $('Selbstauskunft eingereicht Webhook').item.json;
const sa = $('Selbstauskunft laden').item.json;
const inserat = $('Inserat laden').item.json;
const typ = body.typ || inserat.typ || 'miete';

let userPrompt;
if (typ === 'verkauf') {
  userPrompt = `Bewerte dieses Käuferprofil für ein Objekt mit Kaufpreis ${inserat.kaufpreis_eur || 'unbekannt'}€:
- Kaufbudget: ${sa.kaufbudget_eur}€
- Eigenkapital: ${sa.eigenkapital_vorhanden}${sa.eigenkapital_hoehe_eur ? ' (' + sa.eigenkapital_hoehe_eur + '€)' : ''}
- Finanzierung: ${sa.finanzierung_typ}
- Finanzierungsbestätigung: ${sa.finanzierungsbestaetigung}
- Kaufzeitraum: ${sa.kaufzeitraum}
- Kaufgrund: ${sa.kaufgrund}
- In laufendem Verkauf: ${sa.in_laufendem_verkauf ? 'Ja' : 'Nein'}

Antworte NUR mit JSON:
{
  "score": 0-100,
  "begruendung": "2-3 Sätze sachlich",
  "staerken": ["Punkt 1"],
  "risiken": ["Punkt 1"] oder []
}
AGG-Hinweis: Keine Bewertung von Nationalität, Herkunft, Religion, Geschlecht.`;
} else {
  const faktor = inserat.kaltmiete_eur > 0 && sa.nettoeinkommen_eur
    ? (sa.nettoeinkommen_eur / inserat.kaltmiete_eur).toFixed(2)
    : 'n/a';
  userPrompt = `Bewerte diese Mietbewerbung für eine Wohnung mit ${inserat.kaltmiete_eur}€ Kaltmiete:
- Einkommensfaktor: ${faktor}x (Minimum 3x)
- Beschäftigung: ${sa.beschaeftigung_status}, ${sa.arbeitsverhaeltnis || 'n/a'}
- Haushalt: ${sa.haushaltsgroesse} Personen
- Haustiere: ${sa.haustiere ? sa.haustiere_art || 'Ja' : 'Nein'}
- Einzugswunsch: ${sa.einzugstermin}
- Begründung: ${sa.warum_diese_wohnung || 'n/a'}

Antworte NUR mit JSON:
{
  "score": 0-100,
  "begruendung": "2-3 Sätze sachlich",
  "staerken": ["Punkt 1", "Punkt 2"],
  "risiken": ["Punkt 1"] oder []
}
AGG-Hinweis: Keine Bewertung von Nationalität, Herkunft, Religion, Geschlecht.`;
}

return [{
  json: {
    selbstauskunftId: body.selbstauskunftId,
    leadUuid: body.leadUuid,
    typ,
    mistralPrompt: userPrompt
  }
}];

