parameters.jsCode:
const content = $input.first().json.choices?.[0]?.message?.content || '';
const prep = $('Mistral Prompt vorbereiten').item.json;

let analyse;
try {
  const match = content.match(/\{[\s\S]*\}/);
  analyse = JSON.parse(match ? match[0] : content);
} catch (e) {
  analyse = {
    score: 50,
    begruendung: 'Automatische Analyse konnte nicht vollständig geparst werden.',
    staerken: [],
    risiken: ['Parsing-Fehler']
  };
}

const staerken = Array.isArray(analyse.staerken) ? analyse.staerken.join('|') : '';
const risiken = Array.isArray(analyse.risiken) ? analyse.risiken.join('|') : '';

return [{
  json: {
    selbstauskunftId: prep.selbstauskunftId,
    leadUuid: prep.leadUuid,
    score: analyse.score ?? 0,
    begruendung: analyse.begruendung || '',
    staerken,
    risiken,
    analysiert_at: new Date().toISOString()
  }
}];
